import "../css/TrackOrders.css";

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const STATUS_CONFIG = {
    delivered:  { label: 'Delivered',   color: '#1a7a4a' },
    shipped:    { label: 'Shipped',     color: '#185e87' },
    processing: { label: 'Processing',  color: '#b07d12' },
    cancelled:  { label: 'Cancelled',   color: '#c0392b' },
};

function StatusBadge({ status }) {
    const key = (status || '').toLowerCase();
    const cfg = STATUS_CONFIG[key] || { label: status, color: '#555' };
    return (
        <span className="statusBadge" style={{ backgroundColor: cfg.color }}>
            {cfg.label}
        </span>
    );
}

export function TrackOrders(props) {
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();

    useEffect(() => {
        fetchOrders();
    }, []);

    const fetchOrders = async () => {
        try {
            const response = await fetch(
                `http://localhost:8080/orders/placed?userId=${props.userDetails.userId}`,
                { method: 'GET', headers: { 'Content-Type': 'application/json' } }
            );
            if (!response.ok) {
                const msg = await response.text();
                throw new Error(msg);
            }
            const data = await response.json();
            setOrders(data);
        } catch (error) {
            console.error('Error fetching orders:', error);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="trackOrdersPage">
            <div className="trackOrdersHeader">
                <h1 className="trackOrdersTitle">My Orders</h1>
                <button className="backBtn" onClick={() => navigate('/')}>&#8592; Back to Shop</button>
            </div>

            {loading && <p className="trackOrdersMsg">Loading orders…</p>}
            {!loading && orders.length === 0 && (
                <p className="trackOrdersMsg">No orders found.</p>
            )}

            <div className="orderCardsList">
                {orders.map((order, idx) => (
                    <div className="orderCard" key={order.id}>
                        <div className="orderCardHeader">
                            <div className="orderCardMeta">
                                <span className="orderIdLabel">Order</span>
                                <span className="orderIdValue">#{order.invoiceid}</span>
                            </div>
                            <StatusBadge status={order.deliverystatus} />
                        </div>

                        <div className="orderCardDivider" />

                        <div className="orderProductsSection">
                            <p className="orderProductsHeading">Items Ordered</p>
                            <div className="orderProductList">
                                {order.products.map(p => (
                                    <div className="orderProductRow" key={p.productcode}>
                                        <span className="productDot" />
                                        <span className="orderProductName">{p.productname}</span>
                                        <span className="orderProductQty">Qty: {p.quantity}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
}
